const fs = require('fs');

function main() {
    const data = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
    if (data.length === 0) return;
    let idx = 0;
    const N = data[idx++];
    const board = [];
    for (let i = 0; i < N; i++) {
        board[i] = [];
        for (let j = 0; j < N; j++) {
            board[i][j] = data[idx++] - 1;
        }
    }

    const pos = new Array(N * N);
    for (let x = 0; x < N; x++) {
        for (let y = 0; y < N; y++) {
            pos[board[x][y]] = { x, y };
        }
    }

    const INF = 1e9;
    const totalNodes = N * N * 3;

    // dist[i][j] = [moves, changes]
    const dist = new Array(totalNodes);
    for (let i = 0; i < totalNodes; i++) {
        dist[i] = new Array(totalNodes);
        for (let j = 0; j < totalNodes; j++) {
            dist[i][j] = [INF, INF];
        }
        dist[i][i] = [0, 0];
    }

    function hash(x, y, p) {
        return (x * N + y) * 3 + p;
    }

    function inBoard(x, y) {
        return 0 <= x && x < N && 0 <= y && y < N;
    }

    function sumPoint(a, b) {
        return [a[0] + b[0], a[1] + b[1]];
    }

    // Knight moves
    const knightMoves = [[2,1],[-2,1],[2,-1],[-2,-1],[1,2],[-1,2],[1,-2],[-1,-2]];

    for (let x = 0; x < N; x++) {
        for (let y = 0; y < N; y++) {
            // Knight
            for (const [dx, dy] of knightMoves) {
                const nx = x + dx;
                const ny = y + dy;
                if (inBoard(nx, ny)) {
                    const from = hash(x, y, 0);
                    const to = hash(nx, ny, 0);
                    dist[from][to] = [1, 0];
                }
            }
            // Bishop
            for (let i = -N + 1; i <= N - 1; i++) {
                let nx = x + i;
                let ny = y + i;
                if (inBoard(nx, ny)) {
                    const from = hash(x, y, 1);
                    const to = hash(nx, ny, 1);
                    dist[from][to] = [1, 0];
                }
                ny = y - i;
                if (inBoard(nx, ny)) {
                    const from = hash(x, y, 1);
                    const to = hash(nx, ny, 1);
                    dist[from][to] = [1, 0];
                }
            }
            // Rook
            for (let i = 0; i < N; i++) {
                let nx = i;
                let ny = y;
                const from1 = hash(x, y, 2);
                const to1 = hash(nx, ny, 2);
                dist[from1][to1] = [1, 0];

                nx = x;
                ny = i;
                const from2 = hash(x, y, 2);
                const to2 = hash(nx, ny, 2);
                dist[from2][to2] = [1, 0];
            }
            // Piece changes
            for (let i = 0; i < 3; i++) {
                for (let j = 0; j < 3; j++) {
                    if (i !== j) {
                        const from = hash(x, y, i);
                        const to = hash(x, y, j);
                        dist[from][to] = [1, 1];
                    }
                }
            }
        }
    }

    // Floyd-Warshall
    for (let k = 0; k < totalNodes; k++) {
        for (let i = 0; i < totalNodes; i++) {
            if (dist[i][k][0] === INF) continue;
            for (let j = 0; j < totalNodes; j++) {
                const nd = sumPoint(dist[i][k], dist[k][j]);
                if (nd[0] < dist[i][j][0] || (nd[0] === dist[i][j][0] && nd[1] < dist[i][j][1])) {
                    dist[i][j] = nd;
                }
            }
        }
    }

    // DP
    const dp = new Array(N * N);
    for (let i = 0; i < N * N; i++) {
        dp[i] = [[INF, INF], [INF, INF], [INF, INF]];
    }
    dp[0][0] = [0, 0];
    dp[0][1] = [0, 0];
    dp[0][2] = [0, 0];

    for (let i = 0; i < N * N - 1; i++) {
        for (let j = 0; j < 3; j++) {
            if (dp[i][j][0] === INF) continue;
            for (let k = 0; k < 3; k++) {
                const from = hash(pos[i].x, pos[i].y, j);
                const to = hash(pos[i + 1].x, pos[i + 1].y, k);
                const nd = sumPoint(dp[i][j], dist[from][to]);
                if (nd[0] < dp[i + 1][k][0] || (nd[0] === dp[i + 1][k][0] && nd[1] < dp[i + 1][k][1])) {
                    dp[i + 1][k] = nd;
                }
            }
        }
    }

    let ans = dp[N * N - 1][0];
    for (let k = 1; k < 3; k++) {
        const cand = dp[N * N - 1][k];
        if (cand[0] < ans[0] || (cand[0] === ans[0] && cand[1] < ans[1])) {
            ans = cand;
        }
    }

    console.log(`${ans[0]} ${ans[1]}`);
}

main();

